#[test]
fn law_transactions_a_transaction_must_begin_before_it_2() -> ls::Result<()> {
    ls::with_stack(run_78)
}

fn run_78() -> ls::Result<()> {
    let ctx = &mut ls::Context::testing();
    ls::search_replay(
        concat!(
            "lawtwin.kafka::Transactions: \"|a transaction ",
            "must begin before it ends| [reference]",
        ),
        SEARCH_INPUTS_78,
        search_case_78,
    )?;
    {
        let ctx = &mut ls::Context::testing();
        let values = vec![ls::Value::Text(" ".to_owned())];
        law_78(ctx, values[0].clone())?;
    }
    {
        let ctx = &mut ls::Context::testing();
        let values = vec![ls::Value::Text("Hello, World!".to_owned())];
        law_78(ctx, values[0].clone())?;
    }
    {
        let ctx = &mut ls::Context::testing();
        let values = vec![ls::Value::Text("λ日本語😀".to_owned())];
        law_78(ctx, values[0].clone())?;
    }
    {
        let ctx = &mut ls::Context::testing();
        let values = vec![ls::Value::Text("a\u{a}\u{9}\"\\$\u{0}z".to_owned())];
        law_78(ctx, values[0].clone())?;
    }
    {
        let ctx = &mut ls::Context::testing();
        let values = vec![ls::Value::Text("é".to_owned())];
        law_78(ctx, values[0].clone())?;
    }
    {
        let ctx = &mut ls::Context::testing();
        let values = vec![ls::Value::Text("\u{0}aλ😀􏿿".to_owned())];
        law_78(ctx, values[0].clone())?;
    }
    let strategy = proptest::strategy::Just(ls_gen::Case::default()).boxed();
    let strategy = strategy
        .prop_flat_map(|mut case| {
            if case.values.len() != 0 {
                return proptest::strategy::Just(case).boxed();
            }
            let candidate = (|| -> ls::Result<Option<ValueStrategy>> {
                let ctx = &mut case.context;
                let seeds = vec![
                    ls::Value::Text("".to_owned()),
                    ls::Value::Text("".to_owned()),
                    ls::Value::Text(" ".to_owned()),
                    ls::Value::Text("Hello, World!".to_owned()),
                    ls::Value::Text("λ日本語😀".to_owned()),
                    ls::Value::Text("a\u{a}\u{9}\"\\$\u{0}z".to_owned()),
                    ls::Value::Text("é".to_owned()),
                    ls::Value::Text("".to_owned()),
                    ls::Value::Text("\u{0}aλ😀􏿿".to_owned()),
                ];
                let base = Ok::<_, String>(Some(ls_gen::strategy_with_profile("Text", 64)?))?;
                Ok(base.map(|base| ls_gen::seeded(base, seeds)))
            })()
            .unwrap_or_else(|e| panic!("{e}"));
            match candidate {
                Some(s) => (proptest::strategy::Just(case), s)
                    .prop_map(|(mut case, x)| {
                        case.values.push(x);
                        case
                    })
                    .boxed(),
                None => {
                    case.values.clear();
                    proptest::strategy::Just(case).boxed()
                }
            }
        })
        .boxed();
    let refinement = |case: &ls_gen::Case| {
        if case.values.len() != 1 {
            return false;
        }
        let result = valid_78(&mut case.context.clone(), case.values[0].clone());
        result.unwrap_or_else(|e| panic!("{e}"))
    };
    let strategy = strategy.prop_filter(
        concat!(
            "Transactions: \"|a transaction must begin befo",
            "re it ends| [reference] refinement",
        ),
        refinement,
    );
    let config = proptest::test_runner::Config {
        cases: 100,
        max_global_rejects: 10000,
        max_shrink_iters: 1000,
        rng_seed: lawspec_rng_seed(),
        failure_persistence: lawspec_failure_persistence(),
        ..Default::default()
    };
    let check = |mut case: ls_gen::Case| {
        let result = law_78(&mut case.context, case.values[0].clone());
        if result.is_err() {
            ls::search_remember(
                concat!(
                    "lawtwin.kafka::Transactions: \"|a transaction ",
                    "must begin before it ends| [reference]",
                ),
                SEARCH_INPUTS_78,
                &case.values,
            );
        }
        result.map_err(proptest::test_runner::TestCaseError::fail)
    };
    proptest::test_runner::TestRunner::new(config)
        .run(&strategy, check)
        .map_err(|e| format!("{e}"))?;
    Ok(())
}

const SEARCH_INPUTS_78: &[&str] = &["(text)"];

fn search_case_78(values: &[ls::Value]) -> ls::Result<Option<f64>> {
    let ctx = &mut ls::Context::testing();
    if !valid_78(ctx, values[0].clone())? {
        return Ok(None);
    }
    law_78(ctx, values[0].clone())?;
    Ok(Some(0.0))
}
